CREATE DATABASE IF NOT EXISTS soil_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE soil_portal;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(30),village VARCHAR(120),district VARCHAR(120),password_hash VARCHAR(255) NOT NULL,role ENUM('farmer','admin') DEFAULT 'farmer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,crop VARCHAR(120) NOT NULL,sample_notes TEXT,preferred_date DATE,status ENUM('Pending','Approved','Sample Received','Testing','Completed','Rejected') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS soil_reports(id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNIQUE NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,seller_id INT NOT NULL,title VARCHAR(160) NOT NULL,category VARCHAR(80),description TEXT,price DECIMAL(10,2),unit VARCHAR(40),location VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(seller_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS shops(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),category VARCHAR(100),phone VARCHAR(30),address VARCHAR(255),district VARCHAR(120),approved TINYINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS crop_prices(id INT AUTO_INCREMENT PRIMARY KEY,crop VARCHAR(120),market VARCHAR(160),price DECIMAL(10,2),unit VARCHAR(40) DEFAULT 'quintal');
CREATE TABLE IF NOT EXISTS equipment_prices(id INT AUTO_INCREMENT PRIMARY KEY,equipment VARCHAR(160),price DECIMAL(10,2),seller VARCHAR(160));
CREATE TABLE IF NOT EXISTS access_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(100),details VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
INSERT INTO crop_prices(crop,market,price,unit) SELECT 'Paddy','Sample Market',2200,'quintal' WHERE NOT EXISTS(SELECT 1 FROM crop_prices);
INSERT INTO equipment_prices(equipment,price,seller) SELECT 'Manual seed drill',3500,'Sample supplier' WHERE NOT EXISTS(SELECT 1 FROM equipment_prices);
